from pathlib import Path
import base64,zlib,hashlib
ROOT=Path("factory_pc_tool_v069")
ROOT.mkdir(parents=True,exist_ok=True)
FILES={}
FILES['visionsen_factory_tool.py']=('[... ELLIPSIZATION ...]','7298a5720a09d9d64514299f9c58141a62138c7b3c82955a7cfb15d6013bd88b')
FILES['tools/validate_production.py']=('','ab5d9e1d4d5ac39f16fb222a138b727572c47c755315a5aaa876b220f0a950c7')
FILES['RELEASE_NOTES-v0.6.9.md']=('','e8754885e6d8aba0f4bc8337615ffc460f6678e0ac4ddbc6106362250507befc')
for rel,(payload,expected) in FILES.items():
    data=zlib.decompress(base64.b64decode(payload))
    got=hashlib.sha256(data).hexdigest()
    if got!=expected: raise SystemExit(f"payload SHA mismatch {rel}: {got} != {expected}")
    p=ROOT/rel; p.parent.mkdir(parents=True,exist_ok=True); p.write_bytes(data)
    print(f"wrote {rel} sha256={got}")
